"""
Data loader for address-aware format, compatible with jTrans data.py interface.

This module provides DatasetBase and data loading functions that work with
address-aware _extract.pkl files instead of the original format.

Usage:
    # Instead of: from datautils.playdata import DatasetBase
    # Use: from datautils_addressaware.data_addressaware import DatasetBase
    
    # Or load pre-generated paired data:
    functions, metadata = load_addressaware_paired_data('paired_data.pkl')
"""

import os
import pickle
from collections import defaultdict
from functools import reduce
from typing import List, Dict, Tuple, Optional


def parse_filename(filename: str) -> Tuple[Optional[str], Optional[str]]:
    """
    Parse filename to extract project name and optimization level.
    
    Format: {project}-{binary}-{OptLevel}-{hash}_extract.pkl
    Example: 2bwm-git-2bwm-O0-f9579e061f6e200bc50fdae0d8f2a873_extract.pkl
    
    Returns:
        tuple: (project_name, opt_level) or (None, None) if parsing fails
    """
    if not filename.endswith('_extract.pkl'):
        return None, None
    
    base = filename.replace('_extract.pkl', '')
    parts = base.split('-')
    
    if len(parts) < 3:
        return None, None
    
    opt_level = parts[-2]
    valid_opts = ['O0', 'O1', 'O2', 'O3', 'Os', 'Ofast', 'Og']
    if opt_level not in valid_opts:
        return None, None
    
    project = '-'.join(parts[:-2])
    return project, opt_level


class DatasetBase:
    """
    Address-aware version of DatasetBase, compatible with playdata.DatasetBase interface.
    
    Loads _extract.pkl files generated by process.py (address-aware format).
    """
    
    def __init__(self, path: str, prefixfilter=None, all_data=True, opt=None):
        """
        Initialize dataset.
        
        Args:
            path: Path to directory containing _extract.pkl files
            prefixfilter: List of project prefixes to include (only used if all_data=False)
            all_data: If True, include all projects; if False, filter by prefixfilter
            opt: List of optimization levels to include (e.g., ['O0', 'O1', 'O2', 'O3', 'Os'])
        """
        self.path = path
        self.prefixfilter = prefixfilter
        self.all_data = all_data
        self.opt = opt if opt is not None else ['O0', 'O1', 'O2', 'O3', 'Os']
        
        assert os.path.exists(self.path), f"Dataset path does not exist: {self.path}"
        assert (self.prefixfilter is not None) != self.all_data, \
            "You should set prefixfilter with all_data = False"
    
    def get_paired_data_iter(self):
        """
        Iterate over paired function data.
        
        Yields:
            tuple: (project, func_name, opt_data_dict)
                   where opt_data_dict = {opt_level: func_data}
        """
        # Group files by project and optimization level
        proj2pickle = defaultdict(dict)
        
        for filename in os.listdir(self.path):
            if not filename.endswith('_extract.pkl'):
                continue
            
            project, opt_level = parse_filename(filename)
            if project is None or opt_level not in self.opt:
                continue
            
            # Apply prefix filter
            if not self.all_data:
                if not any(project.startswith(prefix) for prefix in self.prefixfilter):
                    continue
            
            pkl_path = os.path.join(self.path, filename)
            proj2pickle[project][opt_level] = pkl_path
        
        # Process each project
        for project, pickle_path_dict in proj2pickle.items():
            if len(pickle_path_dict) < 2:
                continue
            
            # Load all pkl files for this project
            tmp_pickle_dict = {}
            function_lists = []
            
            for opt_level, pkl_path in pickle_path_dict.items():
                with open(pkl_path, 'rb') as f:
                    pkl = pickle.load(f)
                    tmp_pickle_dict[opt_level] = pkl
                    function_lists.append(set(pkl.keys()))
            
            # Find functions that exist in ALL optimization levels
            common_functions = reduce(lambda x, y: x & y, function_lists)
            
            # Yield each common function with all its optimization variants
            for func_name in common_functions:
                ret_func_data = {}
                for opt_level, pkl in tmp_pickle_dict.items():
                    # func_data format: {'func': addr, 'asm': [...], 'raw': b'...', 'cfg': None, 'bai': None}
                    func_data = pkl[func_name]
                    
                    # Convert to tuple format expected by jTrans: (func_addr, asm_list, rawbytes, cfg, bai)
                    ret_func_data[opt_level] = (
                        func_data['func'],      # func_addr
                        func_data['asm'],       # asm_list
                        func_data['raw'],       # rawbytes
                        func_data['cfg'],       # cfg (currently None)
                        func_data['bai']        # bai (currently None)
                    )
                
                yield project, func_name, ret_func_data


def load_addressaware_paired_data(paired_data_path: str) -> Tuple[List, List]:
    """
    Load pre-generated paired data from generate_paired_data.py output.
    
    Args:
        paired_data_path: Path to pickle file generated by generate_paired_data.py
    
    Returns:
        tuple: (functions, metadata)
               - functions: List of function groups, where each group is a list of
                           (func_addr, asm_list, rawbytes, cfg, bai) tuples
               - metadata: List of metadata dicts with project, function, opts info
    """
    with open(paired_data_path, 'rb') as f:
        data = pickle.load(f)
    
    functions = []
    metadata = data['metadata']
    
    # Convert from dict format to tuple format expected by jTrans
    for func_group in data['functions']:
        converted_group = []
        for func_data in func_group:
            # func_data is dict: {'func': addr, 'asm': [...], 'raw': b'...', 'cfg': None, 'bai': None}
            converted_group.append((
                func_data['func'],   # func_addr
                func_data['asm'],    # asm_list
                func_data['raw'],    # rawbytes
                func_data['cfg'],    # cfg
                func_data['bai']     # bai
            ))
        functions.append(converted_group)
    
    return functions, metadata


def load_addressaware_data_direct(
    data_path: str,
    opt: List[str] = None,
    convert_jump: bool = True,
    gen_funcstr_fn = None
) -> Tuple[List, List]:
    """
    Load address-aware data directly from _extract.pkl files.
    Compatible with load_paired_data() in jTrans data.py.
    
    Args:
        data_path: Path to directory containing _extract.pkl files
        opt: List of optimization levels (default: ['O0', 'O1', 'O2', 'O3', 'Os'])
        convert_jump: Whether to convert jump addresses (passed to gen_funcstr_fn)
        gen_funcstr_fn: Function to generate function string from func_data tuple
                        If None, returns raw data without conversion
    
    Returns:
        tuple: (functions, metadata)
               - functions: List of function groups
               - metadata: List of metadata dicts
    """
    if opt is None:
        opt = ['O0', 'O1', 'O2', 'O3', 'Os']
    
    dataset = DatasetBase(data_path, prefixfilter=None, all_data=True, opt=opt)
    
    functions = []
    metadata = []
    
    for project, func_name, opt_data in dataset.get_paired_data_iter():
        func_group = []
        func_meta = {
            'project': project,
            'function': func_name,
            'opts': {}
        }
        
        for opt_level in opt:
            if opt_level in opt_data:
                func_data = opt_data[opt_level]
                
                if gen_funcstr_fn is not None:
                    # Convert to function string
                    func_str = gen_funcstr_fn(func_data, convert_jump)
                    if len(func_str) > 0:
                        func_meta['opts'][opt_level] = len(func_group)
                        func_group.append(func_str)
                else:
                    # Return raw data
                    func_meta['opts'][opt_level] = len(func_group)
                    func_group.append(func_data)
        
        if len(func_group) >= 2:
            functions.append(func_group)
            metadata.append(func_meta)
    
    return functions, metadata


# Example usage and testing
if __name__ == '__main__':
    import sys
    
    if len(sys.argv) < 2:
        print("Usage: python data_addressaware.py <data_path>")
        print("Example: python data_addressaware.py /data/kun/jtransdata/addr_extract/")
        sys.exit(1)
    
    data_path = sys.argv[1]
    
    print(f"Loading address-aware data from: {data_path}")
    print("-" * 60)
    
    # Test DatasetBase
    dataset = DatasetBase(data_path, prefixfilter=None, all_data=True, opt=['O0', 'O1', 'O2', 'O3', 'Os'])
    
    count = 0
    for project, func_name, opt_data in dataset.get_paired_data_iter():
        if count == 0:
            print(f"\nSample paired data:")
            print(f"  Project: {project}")
            print(f"  Function: {func_name}")
            print(f"  Available opts: {list(opt_data.keys())}")
            
            for opt, func_data in opt_data.items():
                func_addr, asm_list, rawbytes, cfg, bai = func_data
                print(f"    {opt}: address={hex(func_addr)}, {len(asm_list)} instructions")
                break
        
        count += 1
        if count >= 10:
            break
    
    print(f"\nTotal function groups found: {count}")
